$_MODULE['<{sudemi}prestashop>sudemi_8af7448f2470dbdf3e3c52b23b771e9d'] = 'Diese Rücksendeanfrage wurde bereits beantwortet (auf sudemi oder von sudemi nach Fristablauf). Es wurde nichts geändert.';
$_MODULE['<{sudemi}prestashop>sudemi_9fba5e140e3eeeef1fb479338a5f0a00'] = 'sudemi hat keine offene Rücksendeanfrage für diese Bestellung. Sie wurde aus der Liste entfernt.';
$_MODULE['<{sudemi}prestashop>sudemi_77045abe2681e10ec8585af1568a531d'] = 'Geben Sie eine Begründung an, um eine Rücksendung abzulehnen. Der Käufer bekommt sie zu sehen.';
$_MODULE['<{sudemi}prestashop>sudemi_f56cb5d64a1b05252377f64a8a6995b3'] = 'sudemi hat diese Antwort nicht angenommen. Eine Ablehnung braucht eine Begründung; prüfen Sie sie und versuchen Sie es erneut.';
$_MODULE['<{sudemi}prestashop>sudemi_98cb3df4ed609dceaddc55efce570395'] = 'Rücksendeanfragen';
$_MODULE['<{sudemi}prestashop>sudemi_0eba7b42b6c53cdc949279b9d1e6ac3c'] = 'Käufer möchten diese zugestellten Bestellungen zurücksenden. Beantworten Sie jede Anfrage vor ihrer Antwortfrist: annehmen oder mit Begründung ablehnen (der Käufer bekommt sie zu sehen). Ohne Antwort entscheidet sudemi. Nach der Annahme erstatten Sie die Bestellung, sobald der Artikel zurück ist.';
